const UUID_V4 = /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-4[0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$/;
const CPF_FORMATADO = /\b\d{3}\.?\d{3}\.?\d{3}-?\d{2}\b/;
const ALLOWLIST = new Set([
  'responder_conversa', 'criar_card_echat', 'atualizar_card_echat', 'mover_card_estagio',
  'registrar_nota_interna', 'transferir_para_humano', 'agendar_followup', 'enviar_template_aprovado',
  'solicitar_segunda_via', 'notificar_equipe_interna', 'registrar_no_vault', 'espelhar_no_notion',
  'consultar_status_leitura', 'abrir_chamado_interno', 'sinalizar_risco', 'bloquear_execucao'
]);

function expired(value) {
  const date = new Date(value);
  return Number.isNaN(date.getTime()) || date.getTime() <= Date.now();
}

function hasSensitivePayload(intent) {
  const message = String(intent?.payload?.mensagem || '');
  return CPF_FORMATADO.test(message) || /\bcpf\b/i.test(message);
}

const input = $input.first().json;
const intent = input.body || input;
const errors = [];
const divergences = [];
const alerts = [];
const tetoDiario = Number($env.TETO_MENSAGENS_DIA || 20);
const mensagensHoje = Number(input.mensagens_automaticas_hoje || intent.mensagens_automaticas_hoje || 0);

const required = ['intent_id', 'created_at', 'actor', 'agent', 'action', 'dry_run', 'target', 'reason', 'source_paths', 'approval', 'payload', 'expires_at'];
for (const key of required) {
  if (!(key in intent)) errors.push(`campo_obrigatorio_ausente:${key}`);
}
if (!UUID_V4.test(String(intent.intent_id || ''))) errors.push('intent_id_invalido');
if (!ALLOWLIST.has(intent.action)) errors.push('acao_fora_da_allowlist');
if (!Array.isArray(intent.source_paths) || intent.source_paths.length === 0) errors.push('source_paths_ausente');
if (typeof intent.dry_run !== 'boolean') errors.push('dry_run_invalido');
if (!intent.approval || typeof intent.approval.required !== 'boolean') errors.push('approval_required_invalido');
if (!intent.target || typeof intent.target.system !== 'string') errors.push('target_system_ausente');
if (typeof intent.reason !== 'string' || intent.reason.length < 20) errors.push('reason_curto_ou_ausente');
if (expired(intent.expires_at)) errors.push('expires_at_vencido');
if (hasSensitivePayload(intent)) errors.push('payload_com_dado_sensivel');

let effectiveIntent = { ...intent };
let status = 'registrado';
let route = 'dry_run';
let reason = 'intencao_valida_modo_espelho';
let keyType = 'intent';
let keyValue = UUID_V4.test(String(intent.intent_id || '')) ? intent.intent_id : `intent-invalida-${$execution.id}`;

if ($env.PAUSAR_DIRETOR_COMERCIAL === 'true') {
  status = 'bloqueado';
  route = 'bloqueado';
  reason = 'kill_switch_ativo';
  alerts.push('alerta_interno_kill_switch');
  keyType = 'policy_log';
} else if (errors.length > 0) {
  status = 'rejeitado';
  route = 'rejeitado';
  reason = errors.join(',');
  keyType = 'policy_log';
} else if (mensagensHoje >= tetoDiario) {
  status = 'bloqueado';
  route = 'bloqueado';
  reason = 'teto_diario_estourado';
  alerts.push('alerta_teto_diario');
  keyType = 'policy_log';
} else if ((intent.autonomy_level === 'L0' || intent.autonomy_level === 'L1' || !intent.autonomy_level) && intent.dry_run === false) {
  effectiveIntent.dry_run = true;
  status = 'registrado_com_divergencia';
  reason = 'dry_run_false_forcado_para_true_em_L0_L1';
  divergences.push(reason);
}

return [{ json: {
  workflow: 'SST · F3 Política',
  status_pre_banco: status,
  route_pre_banco: route,
  reason_pre_banco: reason,
  errors,
  divergences,
  alerts,
  intent: effectiveIntent,
  idempotency_key_type: keyType,
  idempotency_key_value: keyValue,
  metadata: {
    status,
    route,
    reason,
    errors,
    divergences,
    alerts,
    intent_id: intent.intent_id || null,
    action: intent.action || null,
    autonomy_level: intent.autonomy_level || 'L0',
    dry_run: effectiveIntent.dry_run !== false,
    teto_diario: tetoDiario,
    mensagens_automaticas_hoje: mensagensHoje,
    sends_external_message: false,
    mirror_mode: true
  }
} }];

const banco = $input.first().json || {};
const pre = $('Function · validar schema e política').first().json;
let status = pre.status_pre_banco;
let route = pre.route_pre_banco;
let reason = pre.reason_pre_banco;
const duplicate = banco.key_type === 'intent' && banco.inserted !== true;

if (duplicate) {
  status = 'rejeitado';
  route = 'rejeitado';
  reason = 'intent_id_duplicado';
}

let approvalRequired = Boolean(pre.intent?.approval?.required);
if (approvalRequired && status === 'registrado') {
  status = 'fila_humana';
  route = 'fila_aprovacao';
  reason = 'aprovacao_humana_pendente';
}

return [{ json: {
  workflow: 'SST · F3 Política',
  status,
  route,
  reason,
  execute: false,
  sends_external_message: false,
  f5_enabled: false,
  mirror_mode: true,
  dry_run: pre.intent?.dry_run !== false,
  duplicate,
  errors: pre.errors,
  divergences: pre.divergences,
  alerts: pre.alerts,
  idempotency: {
    key_type: banco.key_type,
    key_value: banco.key_value,
    inserted: banco.inserted === true,
    hit_count: banco.hit_count || 0
  },
  intent: pre.intent
} }];
